from __future__ import annotations

from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"expected one match in {path}, got {count}: {old[:120]!r}")
    file.write_text(text.replace(old, new, 1), encoding="utf-8")


def replace_slice(path: str, start_marker: str, end_marker: str, replacement: str) -> None:
    file = Path(path)
    text = file.read_text(encoding="utf-8")
    start = text.find(start_marker)
    if start < 0:
        raise SystemExit(f"start marker missing in {path}: {start_marker[:120]!r}")
    end = text.find(end_marker, start)
    if end < 0:
        raise SystemExit(f"end marker missing in {path}: {end_marker[:120]!r}")
    file.write_text(text[:start] + replacement + text[end:], encoding="utf-8")


